def compute(vars):
    due_by_2017 = vars["v1"] + vars["v2"] + vars["v3"]
    total_commitments = vars["v4"]
    if total_commitments == 0:
        return None
    value = (due_by_2017 / total_commitments) * 100
    return {
        "value": value,
        "trace": {
            "due_by_2017": due_by_2017,
            "total_commitments": total_commitments,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
